# Sources for Sound 28: Shepard tones (lessons/sound-shepard.qmd, apps/shared/lessons/shepard-kit.js). Read 2026-11-28 (Wikipedia only).
_L = ["lessons/sound-shepard.qmd"]
SOURCES = [
    wiki("Shepard tone", "Shepard_tone", _L, who="student", note="Named after Roger Shepard (JASA, December 1964); sine waves separated by octaves under a raised-cosine loudness curve; any smooth tapering curve works as well (Shepard); short gaps make it more convincing [citation needed on the page]; 'a musical barber's pole' (BBC Bang Goes the Theory); Risset's continuous version; examples: Echoes (Meddle, 1971), THX Deep Note (1983), Super Mario 64 (1996), The Dark Knight (2008) Batpod, Dunkirk (2017), Always Ascending (2018), Tenney For Ann (rising), Stockhausen Hymnen."),
    wiki("Tritone paradox", "Tritone_paradox", _L, who="student", note="Pairs of Shepard tones a tritone apart heard as ascending by some and descending by others; Shepard (1963) expected an ambiguous, Necker-cube-like figure; Diana Deutsch (1986) found judgments depend on the tones' positions on the pitch-class circle, and vary with language or dialect (south of England vs California)."),
    wiki("Jean-Claude Risset", "Jean-Claude_Risset", _L, who="teacher", note="French composer, computer-music pioneer (1938-2016); created the continuous Risset scale (Shepard-Risset glissando) after Shepard's discrete scale."),
]
